INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('bank-reading-1', 'N2', 'テレワークの新しい形', '近年、多くの企業はテレワーク制度を導入している。しかし、一部の社員は家での集中力が続かないと感じている。企業側としては、オフィスを自由に使える「ハイブリッド勤務」を新たな選択肢として提示する動きが見られる。導入に当たって、コストや社員の意思を尊重することが重要だと専門家は指摘している。', '[{"s":"近年","h":"近年","l":null},{"s":"、","h":"、","l":null},{"s":"多く","h":"多く","l":null},{"s":"の","h":"の","l":null},{"s":"企業","h":"企業","l":"N3"},{"s":"は","h":"は","l":null},{"s":"テレワーク","h":"テレワーク","l":null},{"s":"制度","h":"制度","l":"N3"},{"s":"を","h":"を","l":null},{"s":"導入","h":"導入","l":"N1"},{"s":"し","h":"し","l":null},{"s":"ている","h":"ている","l":null},{"s":"。","h":"。","l":null},{"s":"しかし","h":"しかし","l":"N5"},{"s":"、","h":"、","l":null},{"s":"一部","h":"一部","l":"N1"},{"s":"の","h":"の","l":null},{"s":"社員","h":"社員","l":null},{"s":"は","h":"は","l":null},{"s":"家","h":"家","l":"N5"},{"s":"で","h":"で","l":null},{"s":"の","h":"の","l":null},{"s":"集中力","h":"集中力","l":null},{"s":"が続かない","h":"が続かない","l":null},{"s":"と","h":"と","l":null},{"s":"感じ","h":"感じ","l":"N3"},{"s":"ている","h":"ている","l":null},{"s":"。","h":"。","l":null},{"s":"企業","h":"企業","l":"N3"},{"s":"側","h":"側","l":"N3"},{"s":"と","h":"と","l":null},{"s":"し","h":"し","l":null},{"s":"ては","h":"ては","l":null},{"s":"、","h":"、","l":null},{"s":"オフィス","h":"オフィス","l":"N3"},{"s":"を","h":"を","l":null},{"s":"自由","h":"自由","l":"N4"},{"s":"に","h":"に","l":null},{"s":"使える","h":"使える","l":null},{"s":"「","h":"「","l":null},{"s":"ハイブリッド","h":"ハイブリッド","l":null},{"s":"勤務","h":"勤務","l":"N1"},{"s":"」","h":"」","l":null},{"s":"を","h":"を","l":null},{"s":"新たな","h":"新たな","l":null},{"s":"選択肢","h":"選択肢","l":null},{"s":"と","h":"と","l":null},{"s":"し","h":"し","l":null},{"s":"て","h":"て","l":null},{"s":"提示","h":"提示","l":"N1"},{"s":"する","h":"する","l":"N5"},{"s":"動き","h":"動く","l":"N4"},{"s":"が","h":"が","l":null},{"s":"見られる","h":"見られる","l":null},{"s":"。","h":"。","l":null},{"s":"導入","h":"導入","l":"N1"},{"s":"に","h":"に","l":null},{"s":"当たって","h":"当たって","l":null},{"s":"、","h":"、","l":null},{"s":"コスト",