INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('bank-reading-2', 'N2', '気候変動とエネルギー政策', '世界中で気候変動への関心が高まる一方、エネルギー政策の見直しが急がれている。専門家は、再生可能エネルギーの比率を高めることは避けられない課題だと指摘している。とりわけ、若者世代には持続可能な社会への理解が求められる。しかし、技術的な課題やコストの問題が残されているのも事実だ。', '[{"s":"世界中","h":"世界中","l":null},{"s":"で","h":"で","l":null},{"s":"気候変動","h":"気候変動","l":null},{"s":"へ","h":"へ","l":null},{"s":"の","h":"の","l":null},{"s":"関心","h":"関心","l":"N3"},{"s":"が","h":"が","l":null},{"s":"高まる","h":"高まる","l":"N1"},{"s":"一方","h":"一方","l":"N3"},{"s":"、","h":"、","l":null},{"s":"エネルギー","h":"エネルギー","l":"N3"},{"s":"政策","h":"政策","l":"N1"},{"s":"の","h":"の","l":null},{"s":"見直し","h":"見直す","l":"N2"},{"s":"が","h":"が","l":null},{"s":"急がれ","h":"急がれる","l":null},{"s":"ている","h":"ている","l":null},{"s":"。","h":"。","l":null},{"s":"専門家","h":"専門家","l":null},{"s":"は","h":"は","l":null},{"s":"、","h":"、","l":null},{"s":"再生可能","h":"再生可能","l":null},{"s":"エネルギー","h":"エネルギー","l":"N3"},{"s":"の","h":"の","l":null},{"s":"比率","h":"比率","l":"N1"},{"s":"を","h":"を","l":null},{"s":"高める","h":"高める","l":"N2"},{"s":"こと","h":"こと","l":"N4"},{"s":"は","h":"は","l":null},{"s":"避けられない","h":"避けられない","l":null},{"s":"課題","h":"課題","l":"N1"},{"s":"だ","h":"だ","l":null},{"s":"と","h":"と","l":null},{"s":"指摘","h":"指摘","l":"N1"},{"s":"し","h":"し","l":null},{"s":"ている","h":"ている","l":null},{"s":"。","h":"。","l":null},{"s":"とりわけ","h":"とりわけ","l":null},{"s":"、","h":"、","l":null},{"s":"若者","h":"若者","l":null},{"s":"世代","h":"世代","l":"N1"},{"s":"には","h":"には","l":null},{"s":"持続可能","h":"持続可能","l":null},{"s":"な","h":"な","l":null},{"s":"社会","h":"社会","l":"N4"},{"s":"へ","h":"へ","l":null},{"s":"の","h":"の","l":null},{"s":"理解","h":"理解","l":"N3"},{"s":"が","h":"が","l":null},{"s":"求められる","h":"求められる","l":null},{"s":"。","h":"。","l":null},{"s":"しかし","h":"しかし","l":"N5"},{"s":"、","h":"、","l":null},{"s":"技術的","h":"技術的","l":null},{"s":"な","h":"な","l":null},{"s":"課題","h":"課題","l":"N1"},{"s":"や","h":"や","l":null},{"s":"コスト","h":"コスト","l":null},{"s":"の","h":"の"