INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('bank-reading-3', 'N2', 'スマホと情報リテラシー', 'スマートフォンの普及により、人々はいつでも情報にアクセスできるようになった。一方で、誤った情報が瞬く間に広がるリスクも増している。ユーザー一人ひとりが情報の出所を確認する意識を持つことが、信頼できる社会を作るうえで不可欠である。', '[{"s":"スマートフォン","h":"スマートフォン","l":null},{"s":"の","h":"の","l":null},{"s":"普及","h":"普及","l":"N2"},{"s":"に","h":"に","l":null},{"s":"より","h":"より","l":"N3"},{"s":"、","h":"、","l":null},{"s":"人々","h":"人々","l":null},{"s":"はい","h":"はい","l":"N5"},{"s":"つ","h":"つ","l":null},{"s":"でも","h":"でも","l":"N5"},{"s":"情報","h":"情報","l":"N3"},{"s":"に","h":"に","l":null},{"s":"アクセス","h":"アクセス","l":null},{"s":"できる","h":"できる","l":"N5"},{"s":"ように","h":"ように","l":null},{"s":"なっ","h":"なる","l":"N5"},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"一方で","h":"一方で","l":null},{"s":"、","h":"、","l":null},{"s":"誤った","h":"誤った","l":null},{"s":"情報","h":"情報","l":"N3"},{"s":"が","h":"が","l":null},{"s":"瞬く間","h":"瞬く間","l":null},{"s":"に","h":"に","l":null},{"s":"広がる","h":"広がる","l":"N3"},{"s":"リスク","h":"リスク","l":null},{"s":"も","h":"も","l":null},{"s":"増し","h":"増す","l":"N3"},{"s":"ている","h":"ている","l":null},{"s":"。","h":"。","l":null},{"s":"ユーザー","h":"ユーザー","l":null},{"s":"一人ひとり","h":"一人ひとり","l":null},{"s":"が","h":"が","l":null},{"s":"情報","h":"情報","l":"N3"},{"s":"の","h":"の","l":null},{"s":"出所","h":"出所","l":null},{"s":"を","h":"を","l":null},{"s":"確認","h":"確認","l":"N3"},{"s":"する","h":"する","l":"N5"},{"s":"意識","h":"意識","l":"N3"},{"s":"を","h":"を","l":null},{"s":"持つ","h":"持つ","l":"N5"},{"s":"こと","h":"こと","l":"N4"},{"s":"が","h":"が","l":null},{"s":"、","h":"、","l":null},{"s":"信頼","h":"信頼","l":"N3"},{"s":"できる","h":"できる","l":"N5"},{"s":"社会","h":"社会","l":"N4"},{"s":"を","h":"を","l":null},{"s":"作る","h":"作る","l":"N5"},{"s":"うえ","h":"うえ","l":null},{"s":"で","h":"で","l":null},{"s":"不可欠","h":"不可欠","l":"N1"},{"s":"で","h":"で","l":null},{"s":"ある","h":"ある","l":"N5"},{"s":"。","h":"。","l":null}]'::jsonb, '[{"word":"普及","reading":"ふきゅう","meaning":"widespread use / diffusion","h