INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('bank-reading-4', 'N2', '少子高齢化と労働力不足', '日本では少子高齢化が急速に進み、労働力不足が深刻な問題となっている。企業は外国人労働者の受け入れやAIの活用によって、この状況を打開しようとしている。しかし、外国人労働者の受け入れに当たっては、言語や文化の違いへの配慮も欠かせない。今後、多様な人材が働きやすい環境を整えることが求められている。', '[{"s":"日本","h":"日本","l":"N3"},{"s":"では","h":"では","l":"N5"},{"s":"少子高齢化","h":"少子高齢化","l":null},{"s":"が","h":"が","l":null},{"s":"急速","h":"急速","l":"N3"},{"s":"に","h":"に","l":null},{"s":"進み","h":"進む","l":"N4"},{"s":"、","h":"、","l":null},{"s":"労働力","h":"労働力","l":null},{"s":"不足","h":"不足","l":"N3"},{"s":"が","h":"が","l":null},{"s":"深刻","h":"深刻","l":"N3"},{"s":"な","h":"な","l":null},{"s":"問題","h":"問題","l":"N5"},{"s":"と","h":"と","l":null},{"s":"なっ","h":"なる","l":"N5"},{"s":"ている","h":"ている","l":null},{"s":"。","h":"。","l":null},{"s":"企業","h":"企業","l":"N3"},{"s":"は","h":"は","l":null},{"s":"外国人","h":"外国人","l":"N5"},{"s":"労働","h":"労働","l":"N3"},{"s":"者","h":"者","l":"N3"},{"s":"の","h":"の","l":null},{"s":"受け入れ","h":"受け入れ","l":"N1"},{"s":"やAIの","h":"やAIの","l":null},{"s":"活用","h":"活用","l":"N3"},{"s":"によって","h":"によって","l":null},{"s":"、","h":"、","l":null},{"s":"この","h":"この","l":"N5"},{"s":"状況","h":"状況","l":"N3"},{"s":"を","h":"を","l":null},{"s":"打開","h":"打開","l":"N1"},{"s":"し","h":"し","l":null},{"s":"よう","h":"よう","l":null},{"s":"と","h":"と","l":null},{"s":"し","h":"し","l":null},{"s":"ている","h":"ている","l":null},{"s":"。","h":"。","l":null},{"s":"しかし","h":"しかし","l":"N5"},{"s":"、","h":"、","l":null},{"s":"外国人","h":"外国人","l":"N5"},{"s":"労働","h":"労働","l":"N3"},{"s":"者","h":"者","l":"N3"},{"s":"の","h":"の","l":null},{"s":"受け入れ","h":"受け入れ","l":"N1"},{"s":"に","h":"に","l":null},{"s":"当たって","h":"当たって","l":null},{"s":"は","h":"は","l":null},{"s":"、","h":"、","l":null},{"s":"言語","h":"言語","l":"N3"},{"s":"や","h":"や","l":null},{"s":"文化","h":"文化","l":"N4"},{"s":"の","h":"の","l":null},{"s":"違い","h":"違う","l":"N5"},{"s":"へ","h":"へ","l":null},{"s":"の","h":"の","l":null},{"s":"配慮","h":"配慮","l":"N1"},{"s":"も欠かせない","h":"も欠かせない","l":null},{"s":"。","h":"。","l":null},{"s":"今後","h":"今後","l":"N3"},{"s":"、","h":"、","l":null},{"s":"多様","h":"多様","l":"N1"},{"s":"な","h":"な","l":null},{"s":"人材","h":"人材","l":"N1"},{"s":"が","h":"が","l":null},{"s":"働き","h":"働く","l":"N5"},{"s":"や","h":"や","l":null},{"s":"すい","h":"すく","l":"N4"},{"s":"環境","h":"環境","l":"N3"},{"s":"を","h":"を","l":null},{"s":"整える","h":"整える","l":"N1"},{"s":"こと","h":"こと","l":"N4"},{"s":"が","h":"が","l":null},{"s":"求められ","h":"求められる","l":null},{"s":"ている","h":"ている","l":null},{"s":"。","h":"。","l":null}]'::jsonb, '[{"word":"少子高齢化","reading":"しょうしこうれいか","meaning":"declining birthrate and aging population","h":"少子高齢化"},{"word":"進み","reading":"すすみ","meaning":"progress","h":"進み"},{"word":"労働力","reading":"ろうどうりょく","meaning":"labor force","h":"労働力"},{"word":"受け入れ","reading":"うけいれ","meaning":"receiving","h":"受け入れ"},{"word":"打開","reading":"だかい","meaning":"breakthrough / resolving (a difficulty)","h":"打開"},{"word":"配慮","reading":"はいりょ","meaning":"consideration","h":"配慮"},{"word":"多様","reading":"たよう","meaning":"diversity","h":"多様"},{"word":"人材","reading":"じんざい","meaning":"man of talent","h":"人材"},{"word":"整える","reading":"ととのえる","meaning":"to put in order","h":"整える"}]'::jsonb, 'bank') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('bank-reading-5', 'N2', 'SNSと若者のコミュニケーション', 'SNSの普及によって、若者同士のコミュニケーションの形は大きく変化した。文字だけでなく、写真や短い動画で気持ちを伝えることが一般的になっている。一方で、対面での会話が減ることにより、直接的な人間関係を築く機会が乏しくなっているという指摘もある。SNSをうまく活用しつつ、対面でのつながりも大切にする姿勢が求められる。', '[{"s":"SNSの","h":"SNSの","l":null},{"s":"普及","h":"普及","l":"N2"},{"s":"によって","h":"によって","l":null},{"s":"、","h":"、","l":null},{"s":"若者","h":"若者","l":null},{"s":"同士","h":"同士","l":"N1"},{"s":"の","h":"の","l":null},{"s":"コミュニケーション","h":"コミュニケーション","l":"N1"},{"s":"の","h":"の","l":null},{"s":"形","h":"形","l":"N4"},{"s":"は","h":"は","l":null},{"s":"大き","h":"大きい","l":"N5"},{"s":"く","h":"く","l":null},{"s":"変化","h":"変化","l":"N3"},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"文字","h":"文字","l":"N3"},{"s":"だけ","h":"だけ","l":null},{"s":"で","h":"で","l":null},{"s":"なく","h":"なく","l":null},{"s":"、","h":"、","l":null},{"s":"写真","h":"写真","l":"N5"},{"s":"や","h":"や","l":null},{"s":"短い","h":"短い","l":"N5"},{"s":"動","h":"動","l":null},{"s":"画","h":"画","l":"N1"},{"s":"で","h":"で","l":null},{"s":"気持ち","h":"気持ち","l":"N4"},{"s":"を","h":"を","l":null},{"s":"伝える","h":"伝える","l":"N4"},{"s":"こと","h":"こと","l":"N4"},{"s":"が","h":"が","l":null},{"s":"一般的","h":"一般的","l":null},{"s":"に","h":"に","l":null},{"s":"なっ","h":"なる","l":"N5"},{"s":"ている","h":"ている","l":null},{"s":"。","h":"。","l":null},{"s":"一方で","h":"一方で","l":null},{"s":"、","h":"、","l":null},{"s":"対面","h":"対面","l":"N1"},{"s":"で","h":"で","l":null},{"s":"の","h":"の","l":null},{"s":"会話","h":"会話","l":"N4"},{"s":"が","h":"が","l":null},{"s":"減る","h":"減る","l":"N3"},{"s":"こと","h":"こと","l":"N4"},{"s":"に","h":"に","l":null},{"s":"より","h":"より","l":"N3"},{"s":"、","h":"、","l":null},{"s":"直接","h":"直接","l":"N3"},{"s":"的","h":"的","l":"N1"},{"s":"な","h":"な","l":null},{"s":"人間","h":"人間","l":"N3"},{"s":"関係","h":"関係","l":"N4"},{"s":"を","h":"を","l":null},{"s":"築く","h":"築く","l":"N1"},{"s":"機会","h":"機会","l":"N4"},{"s":"が","h":"が","l":null},{"s":"乏し","h":"乏しい","l":"N1"},{"s":"く","h":"く","l":null},{"s":"なっ","h":"なる","l":"N5"},{"s":"ている","h":"ている","l":null},{"s":"と","h":"と","l":null},{"s":"いう","h":"いう","l":null},{"s":"指摘","h":"指摘","l":"N1"},{"s":"も","h":"も","l":null},{"s":"ある","h":"ある","l":"N5"},{"s":"。","h":"。","l":null},{"s":"SNSをうまく","h":"SNSをうまく","l":null},{"s":"活用","h":"活用","l":"N3"},{"s":"し","h":"し","l":null},{"s":"つつ","h":"つつ","l":null},{"s":"、","h":"、","l":null},{"s":"対面","h":"対面","l":"N1"},{"s":"で","h":"で","l":null},{"s":"のつな","h":"のつな","l":null},{"s":"がり","h":"がる","l":"N1"},{"s":"も","h":"も","l":null},{"s":"大切","h":"大切","l":"N5"},{"s":"に","h":"に","l":null},{"s":"する","h":"する","l":"N5"},{"s":"姿勢","h":"姿勢","l":"N2"},{"s":"が","h":"が","l":null},{"s":"求められる","h":"求められる","l":null},{"s":"。","h":"。","l":null}]'::jsonb, '[{"word":"普及","reading":"ふきゅう","meaning":"widespread use / diffusion","h":"普及"},{"word":"同士","reading":"どうし","meaning":"fellow","h":"同士"},{"word":"コミュニケーション","reading":"こみゅにけーしょん","meaning":"communication","h":"コミュニケーション"},{"word":"一般的","reading":"いっぱんてき","meaning":"common / general","h":"一般的"},{"word":"対面","reading":"たいめん","meaning":"interview","h":"対面"},{"word":"築く","reading":"きずく","meaning":"to build","h":"築く"},{"word":"指摘","reading":"してき","meaning":"pointing out","h":"指摘"},{"word":"姿勢","reading":"しせい","meaning":"attitude / posture","h":"姿勢"}]'::jsonb, 'bank') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('bank-reading-6', 'N2', '働き方改革と生産性', '長時間労働が問題視される中、多くの企業が働き方改革に取り組んでいる。単に労働時間を減らすだけでなく、業務の効率化を図ることで生産性を高めることが本来の目的である。しかし、業務量が変わらないまま時間だけを減らそうとすると、社員一人当たりの負担が増すおそれもある。改革を成功させるには、業務内容そのものを見直す必要があるだろう。', '[{"s":"長","h":"長い","l":"N5"},{"s":"時間","h":"時間","l":"N5"},{"s":"労働","h":"労働","l":"N3"},{"s":"が","h":"が","l":null},{"s":"問題視","h":"問題視","l":null},{"s":"される","h":"される","l":null},{"s":"中","h":"中","l":"N5"},{"s":"、","h":"、","l":null},{"s":"多く","h":"多く","l":null},{"s":"の","h":"の","l":null},{"s":"企業","h":"企業","l":"N3"},{"s":"が","h":"が","l":null},{"s":"働き","h":"働く","l":"N5"},{"s":"方","h":"方","l":"N5"},{"s":"改革","h":"改革","l":"N1"},{"s":"に","h":"に","l":null},{"s":"取り組ん","h":"取り組む","l":"N1"},{"s":"で","h":"で","l":null},{"s":"いる","h":"いる","l":null},{"s":"。","h":"。","l":null},{"s":"単に","h":"単に","l":"N3"},{"s":"労働","h":"労働","l":"N3"},{"s":"時間","h":"時間","l":"N5"},{"s":"を","h":"を","l":null},{"s":"減らす","h":"減らす","l":"N3"},{"s":"だけ","h":"だけ","l":null},{"s":"で","h":"で","l":null},{"s":"なく","h":"なく","l":null},{"s":"、","h":"、","l":null},{"s":"業務","h":"業務","l":"N1"},{"s":"の","h":"の","l":null},{"s":"効率化","h":"効率化","l":null},{"s":"を","h":"を","l":null},{"s":"図る","h":"図る","l":"N1"},{"s":"こと","h":"こと","l":"N4"},{"s":"で","h":"で","l":null},{"s":"生産性","h":"生産性","l":null},{"s":"を","h":"を","l":null},{"s":"高める","h":"高める","l":"N2"},{"s":"こと","h":"こと","l":"N4"},{"s":"が","h":"が","l":null},{"s":"本来","h":"本来","l":"N2"},{"s":"の","h":"の","l":null},{"s":"目的","h":"目的","l":"N3"},{"s":"で","h":"で","l":null},{"s":"ある","h":"ある","l":"N5"},{"s":"。","h":"。","l":null},{"s":"しかし","h":"しかし","l":"N5"},{"s":"、","h":"、","l":null},{"s":"業務","h":"業務","l":"N1"},{"s":"量","h":"量","l":"N3"},{"s":"が","h":"が","l":null},{"s":"変","h":"変","l":"N4"},{"s":"わらないまま","h":"わらないまま","l":null},{"s":"時間","h":"時間","l":"N5"},{"s":"だけを","h":"だけを","l":null},{"s":"減","h":"減る","l":"N3"},{"s":"ら","h":"ら","l":null},{"s":"そう","h":"そう","l":"N4"},{"s":"と","h":"と","l":null},{"s":"すると","h":"すると","l":"N4"},{"s":"、","h":"、","l":null},{"s":"社員","h":"社員","l":null},{"s":"一人","h":"一人","l":"N5"},{"s":"当たり","h":"当たる","l":"N3"},{"s":"の","h":"の","l":null},{"s":"負担","h":"負担","l":"N1"},{"s":"が","h":"が","l":null},{"s":"増す","h":"増す","l":"N3"},{"s":"お","h":"お","l":null},{"s":"それ","h":"それ","l":"N5"},{"s":"も","h":"も","l":null},{"s":"ある","h":"ある","l":"N5"},{"s":"。","h":"。","l":null},{"s":"改革","h":"改革","l":"N1"},{"s":"を","h":"を","l":null},{"s":"成功","h":"成功","l":"N3"},{"s":"させるには","h":"させるには","l":null},{"s":"、","h":"、","l":null},{"s":"業務","h":"業務","l":"N1"},{"s":"内容","h":"内容","l":"N3"},{"s":"その","h":"その","l":"N5"},{"s":"ものを","h":"ものを","l":null},{"s":"見直す","h":"見直す","l":"N2"},{"s":"必要","h":"必要","l":"N4"},{"s":"が","h":"が","l":null},{"s":"ある","h":"ある","l":"N5"},{"s":"だろう","h":"だろう","l":null},{"s":"。","h":"。","l":null}]'::jsonb, '[{"word":"問題視","reading":"もんだいし","meaning":"to regard as a problem","h":"問題視"},{"word":"改革","reading":"かいかく","meaning":"reform","h":"改革"},{"word":"業務","reading":"ぎょうむ","meaning":"business","h":"業務"},{"word":"効率化","reading":"こうりつか","meaning":"streamlining / making efficient","h":"効率化"},{"word":"図る","reading":"はかる","meaning":"to plot","h":"図る"},{"word":"生産性","reading":"せいさんせい","meaning":"productivity","h":"生産性"},{"word":"高める","reading":"たかめる","meaning":"to raise","h":"高める"},{"word":"本来","reading":"ほんらい","meaning":"essentially","h":"本来"},{"word":"当たり","reading":"あたり","meaning":"hit","h":"当たり"},{"word":"負担","reading":"ふたん","meaning":"burden","h":"負担"},{"word":"見直す","reading":"みなおす","meaning":"to look again","h":"見直す"}]'::jsonb, 'bank') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('bank-reading-7', 'N2', '食品ロス問題への取り組み', 'まだ食べられる食品が大量に廃棄される「食品ロス」が社会問題となっている。スーパーやコンビニでは、賞味期限が近づいた商品を値下げして売り切る取り組みが広がりつつある。また、家庭からの食品ロスを減らすために、必要な分だけ買い、計画的に消費することの重要性も指摘されている。一人ひとりの意識の変化が、この問題の解決につながるだろう。', '[{"s":"まだ","h":"まだ","l":"N5"},{"s":"食べ","h":"食べる","l":"N5"},{"s":"られる","h":"られる","l":null},{"s":"食品","h":"食品","l":"N3"},{"s":"が大","h":"が大","l":null},{"s":"量","h":"量","l":"N3"},{"s":"に","h":"に","l":null},{"s":"廃棄","h":"廃棄","l":"N1"},{"s":"される","h":"される","l":null},{"s":"「","h":"「","l":null},{"s":"食品","h":"食品","l":"N3"},{"s":"ロス","h":"ロス","l":null},{"s":"」","h":"」","l":null},{"s":"が","h":"が","l":null},{"s":"社会","h":"社会","l":"N4"},{"s":"問題","h":"問題","l":"N5"},{"s":"と","h":"と","l":null},{"s":"なっ","h":"なる","l":"N5"},{"s":"ている","h":"ている","l":null},{"s":"。","h":"。","l":null},{"s":"スーパーやコンビニ","h":"スーパーやコンビニ","l":null},{"s":"では","h":"では","l":"N5"},{"s":"、","h":"、","l":null},{"s":"賞味期限","h":"賞味期限","l":null},{"s":"が","h":"が","l":null},{"s":"近","h":"近い","l":"N5"},{"s":"づいた","h":"づいた","l":null},{"s":"商品","h":"商品","l":"N3"},{"s":"を","h":"を","l":null},{"s":"値下げ","h":"値下げ","l":null},{"s":"し","h":"し","l":null},{"s":"て","h":"て","l":null},{"s":"売り切る","h":"売り切る","l":null},{"s":"取り組み","h":"取り組む","l":"N1"},{"s":"が","h":"が","l":null},{"s":"広がり","h":"広がる","l":"N3"},{"s":"つつ","h":"つつ","l":null},{"s":"ある","h":"ある","l":"N5"},{"s":"。","h":"。","l":null},{"s":"また","h":"また","l":"N5"},{"s":"、","h":"、","l":null},{"s":"家庭","h":"家庭","l":"N5"},{"s":"からの","h":"からの","l":null},{"s":"食品","h":"食品","l":"N3"},{"s":"ロスを","h":"ロスを","l":null},{"s":"減らす","h":"減らす","l":"N3"},{"s":"ために","h":"ために","l":null},{"s":"、","h":"、","l":null},{"s":"必要","h":"必要","l":"N4"},{"s":"な","h":"な","l":null},{"s":"分","h":"分","l":"N3"},{"s":"だけ","h":"だけ","l":null},{"s":"買い","h":"買う","l":"N5"},{"s":"、","h":"、","l":null},{"s":"計画的","h":"計画的","l":null},{"s":"に","h":"に","l":null},{"s":"消費","h":"消費","l":"N3"},{"s":"する","h":"する","l":"N5"},{"s":"こと","h":"こと","l":"N4"},{"s":"の","h":"の","l":null},{"s":"重要","h":"重要","l":"N3"},{"s":"性","h":"性","l":"N3"},{"s":"も","h":"も","l":null},{"s":"指摘","h":"指摘","l":"N1"},{"s":"され","h":"され","l":null},{"s":"ている","h":"ている","l":null},{"s":"。","h":"。","l":null},{"s":"一人ひとり","h":"一人ひとり","l":null},{"s":"の","h":"の","l":null},{"s":"意識","h":"意識","l":"N3"},{"s":"の","h":"の","l":null},{"s":"変化","h":"変化","l":"N3"},{"s":"が","h":"が","l":null},{"s":"、","h":"、","l":null},{"s":"この","h":"この","l":"N5"},{"s":"問題","h":"問題","l":"N5"},{"s":"の","h":"の","l":null},{"s":"解決","h":"解決","l":"N3"},{"s":"につな","h":"につな","l":null},{"s":"がる","h":"がる","l":"N1"},{"s":"だろう","h":"だろう","l":null},{"s":"。","h":"。","l":null}]'::jsonb, '[{"word":"廃棄","reading":"はいき","meaning":"annullment","h":"廃棄"},{"word":"賞味期限","reading":"しょうみきげん","meaning":"best-before date","h":"賞味期限"},{"word":"値下げ","reading":"ねさげ","meaning":"price reduction","h":"値下げ"},{"word":"売り切る","reading":"うりきる","meaning":"to sell out completely","h":"売り切る"},{"word":"計画的","reading":"けいかくてき","meaning":"planned / systematic","h":"計画的"},{"word":"指摘","reading":"してき","meaning":"pointing out","h":"指摘"}]'::jsonb, 'bank') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('graded-station-lost', 'N2', 'The station lost-and-found', '昨日、電車で傘を忘れました。家に帰ってから、忘れ物に気づきました。今朝、駅の窓口に行きました。「昨日、青い傘を忘れました」と言うと、係の人は紙を出して、「ここに名前と電話番号を書いてください」と言いました。しばらく待つと、係の人は笑顔で傘を持って来ました。「ほかの駅で見つかりました。忘れ物は三日間、駅で預かります」と言って、笑いました。「持ち主が見つかって、よかったですね」。私は何度もありがとうと言いました。大切な傘が戻ってきて、とても安心しました。窓口の人、ありがとうございました。', '[{"s":"昨日","h":"昨日","l":"N5"},{"s":"、","h":"、","l":null},{"s":"電車","h":"電車","l":"N5"},{"s":"で","h":"で","l":null},{"s":"傘","h":"傘","l":"N5"},{"s":"を","h":"を","l":null},{"s":"忘れ","h":"忘れる","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"家","h":"家","l":"N5"},{"s":"に","h":"に","l":null},{"s":"帰っ","h":"帰る","l":"N5"},{"s":"てから","h":"てから","l":null},{"s":"、","h":"、","l":null},{"s":"忘れ物","h":"忘れ物","l":"N4"},{"s":"に","h":"に","l":null},{"s":"気","h":"気","l":"N4"},{"s":"づきま","h":"づきま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"今朝","h":"今朝","l":"N5"},{"s":"、","h":"、","l":null},{"s":"駅","h":"駅","l":"N5"},{"s":"の","h":"の","l":null},{"s":"窓口","h":"窓口","l":"N2"},{"s":"に","h":"に","l":null},{"s":"行き","h":"行く","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"「","h":"「","l":null},{"s":"昨日","h":"昨日","l":"N5"},{"s":"、","h":"、","l":null},{"s":"青い","h":"青い","l":"N5"},{"s":"傘","h":"傘","l":"N5"},{"s":"を","h":"を","l":null},{"s":"忘れ","h":"忘れる","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"」","h":"」","l":null},{"s":"と","h":"と","l":null},{"s":"言う","h":"言う","l":"N5"},{"s":"と","h":"と","l":null},{"s":"、","h":"、","l":null},{"s":"係","h":"係","l":"N3"},{"s":"の","h":"の","l":null},{"s":"人","h":"人","l":"N5"},{"s":"は","h":"は","l":null},{"s":"紙","h":"紙","l":"N5"},{"s":"を","h":"を","l":null},{"s":"出し","h":"出す","l":"N5"},{"s":"て","h":"て","l":null},{"s":"、",