INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('graded-pharmacy', 'N2', 'At the pharmacy', '先週から、のどが痛くて、少し熱もありました。近くの薬局に行くと、そこの人が「いつからですか」と聞きました。「三日前からです。夜になると、せきも出ます」と答えました。その人は薬を選んで、「これは一日に三回、食後に飲んでください。水をたくさん飲んで、早く寝てくださいね」と言いました。二日飲むと、症状はだいぶ良くなって、のども楽になりました。', '[{"s":"先週","h":"先週","l":"N5"},{"s":"から","h":"から","l":null},{"s":"、","h":"、","l":null},{"s":"のど","h":"のど","l":"N4"},{"s":"が","h":"が","l":null},{"s":"痛","h":"痛い","l":"N5"},{"s":"くて","h":"くて","l":null},{"s":"、","h":"、","l":null},{"s":"少し","h":"少し","l":"N5"},{"s":"熱","h":"熱い","l":"N5"},{"s":"も","h":"も","l":null},{"s":"あり","h":"ある","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"近く","h":"近く","l":"N5"},{"s":"の","h":"の","l":null},{"s":"薬局","h":"薬局","l":"N2"},{"s":"に","h":"に","l":null},{"s":"行く","h":"行く","l":"N5"},{"s":"と","h":"と","l":null},{"s":"、","h":"、","l":null},{"s":"そこ","h":"そこ","l":"N5"},{"s":"の","h":"の","l":null},{"s":"人","h":"人","l":"N5"},{"s":"が","h":"が","l":null},{"s":"「","h":"「","l":null},{"s":"いつか","h":"いつか","l":"N3"},{"s":"ら","h":"ら","l":null},{"s":"で","h":"で","l":null},{"s":"すか","h":"すか","l":null},{"s":"」","h":"」","l":null},{"s":"と","h":"と","l":null},{"s":"聞き","h":"聞く","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"「","h":"「","l":null},{"s":"三日","h":"三日","l":"N5"},{"s":"前","h":"前","l":"N5"},{"s":"から","h":"から","l":null},{"s":"で","h":"で","l":null},{"s":"す","h":"す","l":null},{"s":"。","h":"。","l":null},{"s":"夜","h":"夜","l":"N5"},{"s":"に","h":"に","l":null},{"s":"なる","h":"なる","l":"N5"},{"s":"と","h":"と","l":null},{"s":"、","h":"、","l":null},{"s":"せきも","h":"せきも","l":null},{"s":"出","h":"出る","l":"N5"},{"s":"ます","h":"ます","l":null},{"s":"」","h":"」","l":null},{"s":"と","h":"と","l":null},{"s":"答え","h":"答える","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","