INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('graded-new-neighbour', 'N2', 'Greeting the new neighbour', '先月、この町に引っ越してきました。隣の家にあいさつに行くと、年配の女性が出てきました。「はじめまして。隣に引っ越してきました。これからよろしくお願いします」と言うと、女性は笑って、「こちらこそ。何か困ったことがあれば、遠慮なく言ってくださいね」と言いました。次の日、その女性が手作りのお菓子を持って来てくれました。新しい生活の始まりに、温かい気持ちになりました。', '[{"s":"先月","h":"先月","l":"N5"},{"s":"、","h":"、","l":null},{"s":"この","h":"この","l":"N5"},{"s":"町","h":"町","l":"N5"},{"s":"に","h":"に","l":null},{"s":"引っ越し","h":"引っ越す","l":"N4"},{"s":"てきま","h":"てきま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"隣","h":"隣","l":"N5"},{"s":"の","h":"の","l":null},{"s":"家","h":"家","l":"N5"},{"s":"に","h":"に","l":null},{"s":"あ","h":"あ","l":null},{"s":"いさつに","h":"いさつに","l":null},{"s":"行く","h":"行く","l":"N5"},{"s":"と","h":"と","l":null},{"s":"、","h":"、","l":null},{"s":"年","h":"年","l":"N5"},{"s":"配","h":"配る","l":"N2"},{"s":"の","h":"の","l":null},{"s":"女性","h":"女性","l":"N4"},{"s":"が","h":"が","l":null},{"s":"出","h":"出る","l":"N5"},{"s":"てきま","h":"てきま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"「","h":"「","l":null},{"s":"はじめまして","h":"はじめまして","l":"N2"},{"s":"。","h":"。","l":null},{"s":"隣","h":"隣","l":"N5"},{"s":"に","h":"に","l":null},{"s":"引っ越し","h":"引っ越す","l":"N4"},{"s":"てきま","h":"てきま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"これから","h":"これから","l":"N4"},{"s":"よろしく","h":"よろしく","l":"N3"},{"s":"お願いします","h":"お願いします","l":"N1"},{"s":"」","h":"」","l":null},{"s":"と","h":"と","l":null},{"s":"言う","h":"言う","l":"N5"},{"s":"と","h":"と","l":null},{"s":"、","h":"、","l":null},{"s":"女性","h":"女性","l":"N4"},{"s":"は","h":"は","l":null},{"s":"笑っ","h":"笑う","l":"N4"},{"s":"て","h":"て","l":null},{"s":"、","h":"、","l":null},{"s":"「","h":"「","l":null},{"s":"こちらこそ","h":"こちらこそ","l":"N2"},{"s":"。","h":"。","l":null},{"s":"何か","h":"何か","l":"N3"},{"s":"困っ","h":"困る","l":"N5"},{"s":"た","h":"た","l