INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('graded-dentist-change', 'N2', 'Changing the dentist appointment', '歯医者の予約を変更したくて、電話をかけました。「すみません、来週の水曜日の予約を、金曜日に変えたいのですが」と言うと、受付の人は「金曜日なら、午後三時が空いています」と答えました。歯は時々痛みますが、ひどくはありません。受付の人は「痛みが強いときは、早く治療に来てください」と言いました。治療のとき、麻酔を使うかどうかも聞きました。電話の後、すぐにカレンダーに新しい日時を書きました。これでもう忘れません。', '[{"s":"歯医者","h":"歯医者","l":"N4"},{"s":"の","h":"の","l":null},{"s":"予約","h":"予約","l":"N4"},{"s":"を","h":"を","l":null},{"s":"変更","h":"変更","l":"N3"},{"s":"し","h":"し","l":null},{"s":"たくて","h":"たくて","l":null},{"s":"、","h":"、","l":null},{"s":"電話","h":"電話","l":"N5"},{"s":"を","h":"を","l":null},{"s":"かけ","h":"かける","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"「","h":"「","l":null},{"s":"すみません","h":"すみません","l":"N3"},{"s":"、","h":"、","l":null},{"s":"来週","h":"来週","l":"N5"},{"s":"の","h":"の","l":null},{"s":"水曜日","h":"水曜日","l":"N5"},{"s":"の","h":"の","l":null},{"s":"予約","h":"予約","l":"N4"},{"s":"を","h":"を","l":null},{"s":"、","h":"、","l":null},{"s":"金曜日","h":"金曜日","l":"N5"},{"s":"に","h":"に","l":null},{"s":"変え","h":"変える","l":"N4"},{"s":"たいの","h":"たいの","l":null},{"s":"で","h":"で","l":null},{"s":"すが","h":"すが","l":null},{"s":"」","h":"」","l":null},{"s":"と","h":"と","l":null},{"s":"言う","h":"言う","l":"N5"},{"s":"と","h":"と","l":null},{"s":"、","h":"、","l":null},{"s":"受付","h":"受付","l":"N4"},{"s":"の","h":"の","l":null},{"s":"人","h":"人","l":"N5"},{"s":"は","h":"は","l":null},{"s":"「","h":"「","l":null},{"s":"金曜日","h":"金曜日","l":"N5"},{"s":"なら","h":"なら","l":null},{"s":"、","h":"、","l":null},{"s":"午後","h":"午後","l":"N5"},{"s":"三","h":"三","l":"N5"},{"s":"時","h":"時","l":"N3"},{"s":"が","h":"が","l":null},{"s":"空い","h":"空く","l":"N4"},{"s":"ていま","h":"ていま","l":null},{"s":"す","h":"す","l":null},{"s":"」","h":"」","l":null},{"s":"と","h":"と","l":null},{"s":"答え","h":"答える","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":