INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('graded-city-hall', 'N2', 'Paperwork at city hall', '住所が変わったので、市役所に行きました。窓口で「引っ越しの手続きをしたいです」と言うと、係の人が書類をくれました。名前と住所と生年月日を書いて、出しました。それから椅子に座って、二十分待ちました。やっと私の番になって、用事はすぐに終わりました。帰りに、新しい住所の証明書をもらいました。', '[{"s":"住所","h":"住所","l":"N4"},{"s":"が","h":"が","l":null},{"s":"変わっ","h":"変わる","l":"N4"},{"s":"たの","h":"たの","l":null},{"s":"で","h":"で","l":null},{"s":"、","h":"、","l":null},{"s":"市","h":"市","l":"N4"},{"s":"役所","h":"役所","l":"N2"},{"s":"に","h":"に","l":null},{"s":"行き","h":"行く","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"窓口","h":"窓口","l":"N2"},{"s":"で","h":"で","l":null},{"s":"「","h":"「","l":null},{"s":"引っ越し","h":"引っ越す","l":"N4"},{"s":"の","h":"の","l":null},{"s":"手続き","h":"手続き","l":"N2"},{"s":"を","h":"を","l":null},{"s":"し","h":"し","l":null},{"s":"たい","h":"たい","l":null},{"s":"で","h":"で","l":null},{"s":"す","h":"す","l":null},{"s":"」","h":"」","l":null},{"s":"と","h":"と","l":null},{"s":"言う","h":"言う","l":"N5"},{"s":"と","h":"と","l":null},{"s":"、","h":"、","l":null},{"s":"係","h":"係","l":"N3"},{"s":"の","h":"の","l":null},{"s":"人","h":"人","l":"N5"},{"s":"が","h":"が","l":null},{"s":"書類","h":"書類","l":"N3"},{"s":"を","h":"を","l":null},{"s":"くれ","h":"くれる","l":"N4"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"名前","h":"名前","l":"N5"},{"s":"と","h":"と","l":null},{"s":"住所","h":"住所","l":"N4"},{"s":"と","h":"と","l":null},{"s":"生年月日","h":"生年月日","l":"N2"},{"s":"を","h":"を","l":null},{"s":"書い","h":"書く","l":"N5"},{"s":"て","h":"て","l":null},{"s":"、","h":"、","l":null},{"s":"出し","h":"出す","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"それから","h":"それから","l":"N5"},{"s":"椅子","h":"椅子","l":"N3"},{"s":"に","h":"に","l":null},{"s":"座っ","h":"座る","l":"N5"},{"s":"て","h":"て","l":null},{"s":"、","h":"、",