INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('graded-shopping-street', 'N2', 'The shopping street', '私の家の近くに、市場のある通りがあります。野菜や魚やパンを売る店が並んでいて、夕方はいつもにぎやかです。野菜の店のおじさんは私の顔を覚えてくれて、「今日は大根が安いよ」と声をかけてくれます。買い物の後、公園で家族と買ったパンを食べるのが、私の楽しみです。この町の暮らしが、だんだん好きになってきました。', '[{"s":"私","h":"私","l":"N5"},{"s":"の","h":"の","l":null},{"s":"家","h":"家","l":"N5"},{"s":"の","h":"の","l":null},{"s":"近く","h":"近く","l":"N5"},{"s":"に","h":"に","l":null},{"s":"、","h":"、","l":null},{"s":"市場","h":"市場","l":"N3"},{"s":"の","h":"の","l":null},{"s":"ある","h":"ある","l":"N5"},{"s":"通り","h":"通る","l":"N4"},{"s":"が","h":"が","l":null},{"s":"あり","h":"ある","l":"N5"},{"s":"ます","h":"ます","l":null},{"s":"。","h":"。","l":null},{"s":"野菜","h":"野菜","l":"N5"},{"s":"や","h":"や","l":null},{"s":"魚","h":"魚","l":"N5"},{"s":"や","h":"や","l":null},{"s":"パン","h":"パン","l":"N5"},{"s":"を","h":"を","l":null},{"s":"売る","h":"売る","l":"N5"},{"s":"店","h":"店","l":"N5"},{"s":"が","h":"が","l":null},{"s":"並ん","h":"並ぶ","l":"N5"},{"s":"で","h":"で","l":null},{"s":"いて","h":"いて","l":null},{"s":"、","h":"、","l":null},{"s":"夕方","h":"夕方","l":"N5"},{"s":"はい","h":"はい","l":"N5"},{"s":"つもにぎやか","h":"つもにぎやか","l":null},{"s":"で","h":"で","l":null},{"s":"す","h":"す","l":null},{"s":"。","h":"。","l":null},{"s":"野菜","h":"野菜","l":"N5"},{"s":"の","h":"の","l":null},{"s":"店","h":"店","l":"N5"},{"s":"のおじ","h":"のおじ","l":null},{"s":"さん","h":"さん","l":"N1"},{"s":"は","h":"は","l":null},{"s":"私","h":"私","l":"N5"},{"s":"の顔を","h":"の顔を","l":null},{"s":"覚え","h":"覚える","l":"N5"},{"s":"て","h":"て","l":null},{"s":"くれ","h":"くれる","l":"N4"},{"s":"て","h":"て","l":null},{"s":"、","h":"、","l":null},{"s":"「","h":"「","l":null},{"s":"今日は","h":"今日は","l":"N1"},{"s":"大","h":"大","l":null},{"s":"根","h":"根","l":"N3"},{"s":"が","h":"が","l":null},{"s":"安い","h":"安い","l":"N5"},{"s":"よ","h":"よ","l":null},{"s":"」","h":"」","l":null},{"s":"と","h":"と","l":null},{"s":"声","h":"声","l":"N5"},{"s":"を","h":"を","l":null},{"s":"かけ","h":"かける","l":"N5"},{"s":"て","h":"て","l":null},