INSERT INTO public.reading_passages (id, band, topic, text, tokens, new_word_candidates, source) VALUES ('graded-seaside-town', 'N2', 'A trip to the seaside', '先週の日曜日、初めて海辺の町に行きました。電車で一時間ぐらいです。駅から海まで歩くと、風がとても気持ちよくて、波の音が聞こえました。昼は小さい食堂で魚の定食を食べました。新しい経験でしたが、不思議と落ち着きました。夕方、帰りの電車の中から夕日を見ました。また行きたい町です。', '[{"s":"先週","h":"先週","l":"N5"},{"s":"の","h":"の","l":null},{"s":"日曜日","h":"日曜日","l":"N5"},{"s":"、","h":"、","l":null},{"s":"初めて","h":"初めて","l":"N5"},{"s":"海","h":"海","l":"N5"},{"s":"辺","h":"辺","l":"N5"},{"s":"の","h":"の","l":null},{"s":"町","h":"町","l":"N5"},{"s":"に","h":"に","l":null},{"s":"行き","h":"行く","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"電車","h":"電車","l":"N5"},{"s":"で","h":"で","l":null},{"s":"一時","h":"一時","l":"N3"},{"s":"間","h":"間","l":"N4"},{"s":"ぐらい","h":"ぐらい","l":"N1"},{"s":"で","h":"で","l":null},{"s":"す","h":"す","l":null},{"s":"。","h":"。","l":null},{"s":"駅","h":"駅","l":"N5"},{"s":"から","h":"から","l":null},{"s":"海","h":"海","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"で","h":"で","l":null},{"s":"歩く","h":"歩く","l":"N5"},{"s":"と","h":"と","l":null},{"s":"、","h":"、","l":null},{"s":"風","h":"風","l":"N5"},{"s":"が","h":"が","l":null},{"s":"とても","h":"とても","l":"N5"},{"s":"気持ち","h":"気持ち","l":"N4"},{"s":"よく","h":"よく","l":"N5"},{"s":"て","h":"て","l":null},{"s":"、","h":"、","l":null},{"s":"波","h":"波","l":"N3"},{"s":"の","h":"の","l":null},{"s":"音","h":"音","l":"N4"},{"s":"が","h":"が","l":null},{"s":"聞こえ","h":"聞こえる","l":"N4"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{"s":"昼","h":"昼","l":"N5"},{"s":"は","h":"は","l":null},{"s":"小さい","h":"小さい","l":"N5"},{"s":"食堂","h":"食堂","l":"N5"},{"s":"で","h":"で","l":null},{"s":"魚","h":"魚","l":"N5"},{"s":"の","h":"の","l":null},{"s":"定食","h":"定食","l":"N1"},{"s":"を","h":"を","l":null},{"s":"食べ","h":"食べる","l":"N5"},{"s":"ま","h":"ま","l":null},{"s":"し","h":"し","l":null},{"s":"た","h":"た","l":null},{"s":"。","h":"。","l":null},{